// Extrai o JSON do diagnóstico da resposta da IA e normaliza para o contrato do QA Hub.
const out = $input.first().json;
let text = String(out.text ?? out.output ?? out.response ?? '');
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '').trim();
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('A IA não devolveu JSON: ' + text.slice(0, 200));
// Modelos às vezes quebram linha "de verdade" dentro das strings do JSON: escapa.
let json = '', inString = false, escaped = false;
for (const ch of text.slice(start, end + 1)) {
  if (inString && !escaped && (ch === '\n' || ch === '\r' || ch === '\t')) {
    json += ch === '\n' ? '\\n' : ch === '\r' ? '' : '\\t';
    continue;
  }
  if (ch === '"' && !escaped) inString = !inString;
  escaped = ch === '\\' && !escaped;
  json += ch;
}
let data;
try {
  data = JSON.parse(json);
} catch (e) {
  throw new Error('JSON inválido na resposta da IA: ' + e.message);
}
const groups = (Array.isArray(data.groups) ? data.groups : [])
  .filter((g) => g && g.title && Array.isArray(g.executions) && g.executions.length)
  .map((g) => ({
    title: String(g.title).trim(),
    category: String(g.category || 'produto').toLowerCase(),
    confidence: String(g.confidence || 'baixa').toLowerCase(),
    executions: g.executions.map(Number).filter(Number.isFinite),
    evidence: String(g.evidence || '').trim(),
    action: String(g.action || '').trim(),
  }));
if (!groups.length) throw new Error('Nenhum grupo válido na resposta da IA');
return [{ json: { summary: String(data.summary || '').trim(), groups } }];
